package app.auditlog

import app.common.CursorPage

/** Keeps audit_log rows in memory, for tests and for trying the services without a database. */
class MemoryAuditLogRepository : AuditLogRepository {
    private val rows = linkedMapOf<List<Any?>, AuditLog>()

    /** The key of a row, as a list of its key values. */
    private fun keyOf(row: AuditLog): List<Any?> = listOf(row.at, row.message)

    /** Orders two keys value by value. */
    @Suppress("UNCHECKED_CAST")
    private fun compareKeys(a: List<Any?>, b: List<Any?>): Int {
        for (index in a.indices) {
            val order = compareValues(a[index] as Comparable<Any>?, b[index] as Comparable<Any>?)
            if (order != 0) return order
        }
        return 0
    }

    private fun visible(): List<AuditLog> =
        rows.values.filter { true }.sortedWith { a, b -> compareKeys(keyOf(a), keyOf(b)) }

    override fun list(after: List<Any>?, limit: Int): CursorPage<AuditLog> {
        val rows = visible().filter { after == null || compareKeys(keyOf(it), after) > 0 }
        val items = rows.take(limit)
        return CursorPage(items, if (rows.size > limit) keyOf(items.last()).map { it!! } else null)
    }
}

