package app.auditlog

import app.common.CursorPage
import java.time.OffsetDateTime
import org.jetbrains.exposed.v1.core.ResultRow
import org.jetbrains.exposed.v1.core.SortOrder
import org.jetbrains.exposed.v1.core.and
import org.jetbrains.exposed.v1.core.eq
import org.jetbrains.exposed.v1.core.greater
import org.jetbrains.exposed.v1.core.or
import org.jetbrains.exposed.v1.jdbc.Database
import org.jetbrains.exposed.v1.jdbc.selectAll
import org.jetbrains.exposed.v1.jdbc.transactions.transaction as exposedTransaction

/** Keeps audit_log rows in the database, through Exposed. Every call joins the transaction already open, or is committed at once. */
class SqlAuditLogRepository(private val db: Database) : AuditLogRepository {
    override fun list(after: List<Any>?, limit: Int): CursorPage<AuditLog> {
        return exposedTransaction(db) {
            val query = if (after == null) AuditLogTable.selectAll() else AuditLogTable.selectAll().where { (AuditLogTable.at greater (after[0] as OffsetDateTime)) or ((AuditLogTable.at eq (after[0] as OffsetDateTime)) and (AuditLogTable.message greater (after[1] as String))) }
            val rows = query.orderBy(AuditLogTable.at to SortOrder.ASC, AuditLogTable.message to SortOrder.ASC).limit(limit + 1).map { toEntity(it) }
            val items = rows.take(limit)
            CursorPage(items, if (rows.size > limit) listOf<Any>(items.last().at!!, items.last().message!!) else null)
        }
    }

    private fun toEntity(row: ResultRow): AuditLog = AuditLog().also { fill(it, row) }

    private fun fill(entity: AuditLog, row: ResultRow) {
        entity.at = row[AuditLogTable.at]
        entity.message = row[AuditLogTable.message]
    }
}

