    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: OrderLine?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["orderId"]
            if (value == null) {
                if (creating || "orderId" in values) errors += FieldError("order_id", "is required")
            }
        }
        run {
            val value = values["line"]
            if (value == null) {
                if (creating || "line" in values) errors += FieldError("line", "is required")
            }
        }
        run {
            val value = values["productId"]
            if (value == null) {
                if (creating || "productId" in values) errors += FieldError("product_id", "is required")
            }
        }
        run {
            val value = values["quantity"]
            if (value == null) {
                if (creating || "quantity" in values) errors += FieldError("quantity", "is required")
            }
        }
        run {
            val orderId = if ("orderId" in values) values["orderId"] as Long? else current?.orderId
            if (orderId != null && uow.orders.findById(orderId) == null)
                errors += FieldError("order_id", "no Order has this key")
        }
        run {
            val productId = if ("productId" in values) values["productId"] as Long? else current?.productId
            if (productId != null && uow.products.findById(productId) == null)
