    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: OrderLine?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: OrderLine, values: Map<String, Any?>) {
        if ("orderId" in values) entity.orderId = values["orderId"] as Long?
        if ("line" in values) entity.line = values["line"] as Int?
        if ("productId" in values) entity.productId = values["productId"] as Long?
        if ("quantity" in values) entity.quantity = values["quantity"] as Int?
    }

    /** The OrderLine with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, orderId: Long, line: Int): OrderLine =
        uow.orderLines.findByOrderIdAndLine(orderId, line) ?: throw NotFoundException("OrderLine", listOf(orderId, line))

    /** The values an update gives, by field. */
    private fun given(changes: OrderLineChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        changes.productId?.let { values["productId"] = it.orElse(null) }
        changes.quantity?.let { values["quantity"] = it.orElse(null) }
