            val rows = query.orderBy(OrderLineTable.orderId to SortOrder.ASC, OrderLineTable.line to SortOrder.ASC).limit(limit + 1).map { toEntity(it) }
            val items = rows.take(limit)
            CursorPage(items, if (rows.size > limit) listOf<Any>(items.last().orderId!!, items.last().line!!) else null)
        }
    }

    override fun listByOrderId(orderId: Long): List<OrderLine> {
        return exposedTransaction(db) {
            OrderLineTable.selectAll().where { OrderLineTable.orderId eq orderId }.orderBy(OrderLineTable.orderId to SortOrder.ASC, OrderLineTable.line to SortOrder.ASC).map { toEntity(it) }
        }
    }

    override fun listByProductId(productId: Long): List<OrderLine> {
        return exposedTransaction(db) {
            OrderLineTable.selectAll().where { OrderLineTable.productId eq productId }.orderBy(OrderLineTable.orderId to SortOrder.ASC, OrderLineTable.line to SortOrder.ASC).map { toEntity(it) }
        }
    }

    override fun insert(entity: OrderLine): OrderLine {
        return write {
            OrderLineTable.insert { row ->
                entity.orderId?.let { row[OrderLineTable.orderId] = it }
                entity.line?.let { row[OrderLineTable.line] = it }
                entity.productId?.let { row[OrderLineTable.productId] = it }
                entity.quantity?.let { row[OrderLineTable.quantity] = it }
            }
            fill(entity, OrderLineTable.selectAll().where { (OrderLineTable.orderId eq entity.orderId!!) and (OrderLineTable.line eq entity.line!!) }.single())
            entity
        }
    }

    override fun update(entity: OrderLine): OrderLine {
        return write {
            OrderLineTable.update({ (OrderLineTable.orderId eq entity.orderId!!) and (OrderLineTable.line eq entity.line!!) }) { row ->
                entity.productId?.let { row[OrderLineTable.productId] = it }
                entity.quantity?.let { row[OrderLineTable.quantity] = it }
            }
            entity
        }
    }

    override fun delete(entity: OrderLine): Unit {
        write {
            OrderLineTable.deleteWhere { (OrderLineTable.orderId eq entity.orderId!!) and (OrderLineTable.line eq entity.line!!) }
        }
    }

    private fun toEntity(row: ResultRow): OrderLine = OrderLine().also { fill(it, row) }

    private fun fill(entity: OrderLine, row: ResultRow) {
        entity.orderId = row[OrderLineTable.orderId]
        entity.line = row[OrderLineTable.line]
        entity.productId = row[OrderLineTable.productId]
        entity.quantity = row[OrderLineTable.quantity]
    }

    /** Runs a write in a transaction; a database refusal (a unique value, a row still pointed to) becomes a ConflictException. */
    private fun <T> write(work: () -> T): T =
        try {
            exposedTransaction(db) { work() }
        } catch (error: ExposedSQLException) {
            // SQLSTATE class 23: the change breaks a constraint (SQLite says so in its message)
            if (!error.sqlState.startsWith("23") && error.cause?.message?.contains("SQLITE_CONSTRAINT") != true) throw error
            throw ConflictException("OrderLine", "the database refused the change: ${error.cause?.message}")
