        }
    }

    override fun insert(entity: Product): Product {
        return write {
            val statement = ProductTable.insert { row ->
                entity.categoryId?.let { row[ProductTable.categoryId] = it }
                entity.name?.let { row[ProductTable.name] = it }
                entity.price?.let { row[ProductTable.price] = it }
                entity.status?.let { row[ProductTable.status] = it }
                entity.version?.let { row[ProductTable.version] = it }
                entity.deletedAt?.let { row[ProductTable.deletedAt] = it }
            }
            entity.id = statement[ProductTable.id]
            fill(entity, ProductTable.selectAll().where { ProductTable.id eq entity.id!! }.single())
