    }

    override fun update(entity: Product): Product {
        return write {
            ProductTable.update({ ProductTable.id eq entity.id!! }) { row ->
                entity.categoryId?.let { row[ProductTable.categoryId] = it }
                entity.name?.let { row[ProductTable.name] = it }
                entity.price?.let { row[ProductTable.price] = it }
                entity.status?.let { row[ProductTable.status] = it }
                entity.version?.let { row[ProductTable.version] = it }
                row[ProductTable.deletedAt] = entity.deletedAt
            }
            entity
        }
