    fun createProductTag(productTag: ProductTag): ProductTag {
        val values = mapOf(
            "productId" to productTag.productId,
            "tagId" to productTag.tagId,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
