    /** Changes the given values of a ProductTag. */
    fun updateProductTag(productId: Long, tagId: Long, changes: ProductTagChanges): ProductTag {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, productId, tagId)
            checkValues(uow, values, current)
            applyValues(current, values)
            uow.productTags.update(current)
        }
    }

    /** Deletes a ProductTag. */
    fun deleteProductTag(productId: Long, tagId: Long) {
        unitOfWork.transaction { uow ->
            val current = find(uow, productId, tagId)
            uow.productTags.delete(current)
        }
    }

    /** The product_tags with this product_id. */
    fun listProductTagsByProductId(productId: Long): List<ProductTag> = unitOfWork.productTags.listByProductId(productId)

    /** The product_tags with this tag_id. */
    fun listProductTagsByTagId(tagId: Long): List<ProductTag> = unitOfWork.productTags.listByTagId(tagId)

