    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: ProductTag?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["productId"]
            if (value == null) {
                if (creating || "productId" in values) errors += FieldError("product_id", "is required")
            }
        }
        run {
            val value = values["tagId"]
            if (value == null) {
                if (creating || "tagId" in values) errors += FieldError("tag_id", "is required")
            }
        }
        run {
            val productId = if ("productId" in values) values["productId"] as Long? else current?.productId
            if (productId != null && uow.products.findById(productId) == null)
                errors += FieldError("product_id", "no Product has this key")
        }
        run {
            val tagId = if ("tagId" in values) values["tagId"] as Long? else current?.tagId
            if (tagId != null && uow.tags.findById(tagId) == null)
                errors += FieldError("tag_id", "no Tag has this key")
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("ProductTag", errors)
    }

