    private fun applyValues(entity: ProductTag, values: Map<String, Any?>) {
        if ("productId" in values) entity.productId = values["productId"] as Long?
        if ("tagId" in values) entity.tagId = values["tagId"] as Long?
    }

    /** The ProductTag with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, productId: Long, tagId: Long): ProductTag =
        uow.productTags.findByProductIdAndTagId(productId, tagId) ?: throw NotFoundException("ProductTag", listOf(productId, tagId))

    /** The values an update gives, by field. */
    private fun given(changes: ProductTagChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        return values
    }
}

