    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Tag?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["label"]
            if (value == null) {
                if (creating || "label" in values) errors += FieldError("label", "is required")
            } else {
                if (value is String && value.length > 30) errors += FieldError("label", "is longer than 30 characters")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Tag", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Tag?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Tag, values: Map<String, Any?>) {
        if ("label" in values) entity.label = values["label"] as String?
    }

    /** The Tag with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: Long): Tag =
        uow.tags.findById(id) ?: throw NotFoundException("Tag", id)

    /** The values an update gives, by field. */
    private fun given(changes: TagChanges): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        changes.label?.let { values["label"] = it.orElse(null) }
        return values
    }
}

